{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.plus_size_eoq as with plus_size as ( select sku_group, (sum(inventory_on_inward_date*ros)/sum(inventory_on_inward_date))::int as adj_ros from snitch_db.maplemonk.original_ros_str_eoq where sku_group like \'4MBG%\' group by 1 ), category as ( select sku_group, category from snitch_db.maplemonk.availability_master_v2 where sku_group like \'4MBG%\' ), main as ( select a.*, b.category from plus_size a left join category b on a.sku_group = b.sku_group ), ros_filter as ( select category, p75 from snitch_db.maplemonk.category_l1category_ros_filter_eoq where l1_category = \'plus_size\' ), repeat_decision as ( select a.* , b.p75, case when adj_ros >= p75 then \'yes\' else \'no\' end as repeat_flag from main a left join ros_filter b on a.category = b.category where adj_ros >= p75 ), current_inv as ( select sku_group, xl3_units, xl4_units, xl5_units, xl6_units from snitch_db.maplemonk.availability_master_v2 where sku_group like \'4MBG%\' ), size_sales as ( select sum(case when size = \'3XL\' then gross_quantity end) as xl3_size, sum(case when size = \'4XL\' then gross_quantity end) as xl4_size, sum(case when size = \'5XL\' then gross_quantity end) as xl5_size, sum(case when size = \'6XL\' then gross_quantity end) as xl6_size from snitch_db.maplemonk.horizontal_sales_categories where sku_group like \'4MBG%\' ), sku_size_sales as ( select sku_group, sum(case when size = \'3XL\' then gross_quantity end) as xl3_size, sum(case when size = \'4XL\' then gross_quantity end) as xl4_size, sum(case when size = \'5XL\' then gross_quantity end) as xl5_size, sum(case when size = \'6XL\' then gross_quantity end) as xl6_size from snitch_db.maplemonk.horizontal_sales_categories where sku_group like \'4MBG%\' group by 1 ), size_ratio as ( select xl3_size/(xl3_size+xl4_size+xl5_size+xl6_size) as xl3_ratio, xl4_size/(xl3_size+xl4_size+xl5_size+xl6_size) as xl4_ratio, xl5_size/(xl3_size+xl4_size+xl5_size+xl6_size) as xl5_ratio, xl6_size/(xl3_size+xl4_size+xl5_size+xl6_size) as xl6_ratio from size_sales ), req_quant as ( select sku_group, adj_ros*90 as quant_req from repeat_decision ), size_wise_remaining as ( select a.sku_group, greatest(a.xl3_units-xl3_size,0) as xl3_remaining, greatest(a.xl4_units-xl4_size,0) as xl4_remaining, greatest(a.xl5_units-xl5_size,0) as xl5_remaining, greatest(a.xl6_units-xl6_size,0) as xl6_remaining from current_inv a join sku_size_sales b on a.sku_group = b.sku_group ), final_check as ( select a.sku_group, (greatest(((quant_req*b.xl3_ratio)),0))::int as xl3_order_quant, (greatest(((quant_req*b.xl4_ratio)),0))::int as xl4_order_quant, (greatest(((quant_req*b.xl5_ratio)),0))::int as xl5_order_quant, (greatest(((quant_req*b.xl6_ratio)),0))::int as xl6_order_quant, (greatest(((quant_req*b.xl3_ratio)-xl3_remaining),0))::int + (greatest(((quant_req*b.xl4_ratio)-xl4_remaining),0))::int + (greatest(((quant_req*b.xl5_ratio)-xl5_remaining),0))::int + (greatest(((quant_req*b.xl6_ratio)-xl6_remaining),0))::int as total_order_quant from req_quant a join size_ratio b left join size_wise_remaining c on a.sku_group = c.sku_group ), prod_info as ( select sku_group, initcap(product_name) as title, original_price as mrp, inventory+offline_inventory as inventory from snitch_db.maplemonk.product_journey ), factory_suggestion as ( Select adjusted_sku as sku_group,factory_ from ( SELECT adjusted_sku, factory_, ROW_NUMBER() OVER (PARTITION BY ADJUSTED_SKU ORDER BY DATE DESC) AS RN FROM ( SELECT CASE WHEN \"SKU Number\" LIKE \'R%\' THEN SUBSTR(\"SKU Number\", 2) ELSE \"SKU Number\" END AS adjusted_sku, case when \"Factory Vendor Code\" in (\'01 - SSTC\', \'03 - Leandro\', \'13 - Kharva\', \'18 - Expert\', \'16 - Thandeshwara\', \'09 - Nalanda\', \'05 - Sai Textiles\', \'06 - Alagesh\', \'MQ - M Square\', \'14 - Lohith Creations\', \'IN - Mohit\', \'19 - S R Apparels\', \'Navkar\', \'02 - Kasturi Creation\', \'08 - Vignesh\', \'21-BLUE MONKEY\', \'KU - Kunal\', \'AC - Asian Clothing\', \'07 - K P\', \'15 - Prestige\', \'VN - Vanitha Garments\', \'10 - Adeep \') then \"Factory Vendor Code\" else factory end as factory_, TO_DATE(\"Date Issued\", \'DD-MM-YYYY\') AS DATE FROM snitch_db.maplemonk.PRODUCT_TRACKING_HIDDEN_SHIPPED UNION ALL Select CASE WHEN sku LIKE \'R%\' THEN SUBSTR(sku, 2) ELSE sku END AS adjusted_sku, factory_name, CASE WHEN TRY_TO_DATE(date_issued, \'DD-MM-YYYY\') IS NOT NULL THEN TO_DATE(date_issued, \'DD-MM-YYYY\') ELSE TO_DATE(date_issued, \'DD/MM/YYYY\') END AS DATE, from snitch_db.maplemonk.WORK_ORDERS_final_NEW_MAIN WHERE SKU_STATUS_ =\'Delivered\' and date_issued !=\'Delivered\' UNION ALL SELECT ADJUSTED_SKU, FACTORY_NAME, ISSUED_DATE FROM SNITCH_DB.MAPLEMONK.PRODUCTION_DATA WHERE STATUS = \'Delivered\' AND ISSUED_DATE IS NOT NULL ) ) sub WHERE RN = 1 ), images_data as ( SELECT LEFT(variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING))) AS sku_group, image.value:\"preview\":\"image\":\"url\"::string AS image_url FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => parse_json(t.media)) AS image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant, WHERE image.value:\"mediaContentType\"::string = \'IMAGE\' qualify ROW_NUMBER() OVER (PARTITION BY t.id ORDER BY image.index) = 1 ), size_production_ratio_pre as ( select sku_group, CAST( ARRAY_MIN(ARRAY_CONSTRUCT_COMPACT( NULLIF(xl3_order_quant, 0), NULLIF(xl4_order_quant, 0), NULLIF(xl5_order_quant, 0), NULLIF(xl6_order_quant, 0) )) AS INTEGER) AS least_quant from final_check ), size_ratio_plus_size_pre as ( select a.sku_group, xl3_order_quant/least_quant as xl3_ratio, xl4_order_quant/least_quant as xl4_ratio, xl5_order_quant/least_quant as xl5_ratio, xl6_order_quant/least_quant as xl6_ratio from final_check a left join size_production_ratio_pre b on a.sku_group = b.sku_group ), size_ratio_plus_size as ( select sku_group, concat(round(xl3_ratio,1),\' : \',round(xl4_ratio,1),\' : \',round(xl5_ratio,1),\' : \',round(xl6_ratio,1)) as size_ratio from size_ratio_plus_size_pre ) select a.*, b.title, b.mrp, b.inventory, c.factory_ as factory, d.image_url, e.size_ratio from final_check a left join prod_info b on a.sku_group = b.sku_group left join factory_suggestion c on a.sku_group = c.sku_group left join images_data d on a.sku_group = d.sku_group left join size_ratio_plus_size e on a.sku_group = e.sku_group ; create or replace table snitch_db.maplemonk.plus_new_size_ratio as with size_sales as ( select sum(case when size = \'3XL\' then gross_quantity end) as xl3_size, sum(case when size = \'4XL\' then gross_quantity end) as xl4_size, sum(case when size = \'5XL\' then gross_quantity end) as xl5_size, sum(case when size = \'6XL\' then gross_quantity end) as xl6_size from snitch_db.maplemonk.horizontal_sales_categories where sku_group like \'4MBG%\' ) select round(xl3_size/least(xl3_size,xl4_size,xl5_size,xl6_size),1) as xl3_ratio, round(xl4_size/least(xl3_size,xl4_size,xl5_size,xl6_size),1) as xl4_ratio, round(xl5_size/least(xl3_size,xl4_size,xl5_size,xl6_size),1) as xl5_ratio, round(xl6_size/least(xl3_size,xl4_size,xl5_size,xl6_size),1) as xl6_ratio from size_sales ;",
                    "transaction": true
                }
            ) }}
